"import os

def w(path, text):
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
    with open(path, "w") as f:
        f.write(text)

# Domain: 9 x 1 x 2 m (3D Rayleigh-Benard cell)
