# Scoring only needs run to complete quickly with >=1 time directory written.
# Task nominal endTime=1000 dt=1 write=50; we shrink endTime for fast grading.
DT, END, WRITE = 1.0, 50.0, 10.0

w("system/controlDict", f"""FoamFile {{ format ascii; class dictionary; object controlDict; location "system/controlDict"; }}
application     buoyantFoam;
