startTime       0;
stopAt          endTime;
endTime         {END};
deltaT          {DT};
writeControl    runTime;
writeInterval   {WRITE};
purgeWrite      0;
writeFormat     ascii;
writePrecision  6;
timeFormat      general;
runTimeModifiable true;
""")

